IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Kış Aylarında Cilt Neminin Önemi') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Kış Aylarında Cilt Neminin Önemi',N'Soğuk havada cildinizi koruyun',N'<p>Kış aylarında hava nemi düşer ve cildiniz kurumaya başlar. Günde en az 2 litre su içmek ve nemlendirici kullanmak cildinizin sağlığını korur. Doğal zeytinyağlı kremler bu dönemde idealdir.</p>',N'blog-1',N'img/blog-cilt.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Cilt Bakımı' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424748',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'C Vitamini Serumu Neden Kullanmalısınız?') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'C Vitamini Serumu Neden Kullanmalısınız?',N'Parlaklık ve canlılık için',N'<p>C vitamini serumu cilt tonu eşitsizliklerini giderir, leke açar ve antioksidan koruması sağlar. Sabah rutininize ekleyin ve farkı haftalarca görün.</p>',N'blog-2',N'img/blog-vitamin.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Cilt Bakımı' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424746',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Peeling Nedir ve Ne Zaman Yapılmalı?') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Peeling Nedir ve Ne Zaman Yapılmalı?',N'Hücre yenilemenin sırrı',N'<p>Kimyasal ya da mekanik peeling, ölü hücreleri uzaklaştırır ve cildi yeniler. Haftada 1-2 kez uygulamak yeterlidir; hassas ciltler için daha az sıklık önerilir.</p>',N'blog-3',N'img/blog-peeling.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Cilt Bakımı' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424744',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'İsveç Masajı ve Faydaları') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'İsveç Masajı ve Faydaları',N'Kasları gevşeten klasik teknik',N'<p>İsveç masajı, uzun ve kayıcı vuruşlarla yapılır. Kan dolaşımını iyileştirir, kas gerginliğini azaltır ve derin bir rahatlama sağlar. Haftada bir seans uzun vadeli fayda sunar.</p>',N'blog-4',N'img/blog-isvec.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Masaj Teknikleri' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424741',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Derin Doku Masajı Kimler İçin Uygundur?') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Derin Doku Masajı Kimler İçin Uygundur?',N'Kronik ağrılar için çözüm',N'<p>Derin doku masajı, kasların alt katmanlarına ulaşarak kronik ağrıyı ve kas spazmını çözer. Atletler ve masa başı çalışanlar için özellikle önerilir.</p>',N'blog-5',N'img/blog-derindoku.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Masaj Teknikleri' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424739',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Refleksoloji: Ayak Noktalarından Şifa') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Refleksoloji: Ayak Noktalarından Şifa',N'Vücudun haritası ayaklarda',N'<p>Refleksoloji, ayakta bulunan basınç noktalarına belirli tekniklerle baskı uygulanarak organların uyarılması prensibine dayanır. Stres azaltmada ve enerji dengelenmesinde etkilidir.</p>',N'blog-6',N'img/blog-refleksoloji.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Masaj Teknikleri' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424723',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'5 Dakikalık Nefes Meditasyonu') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'5 Dakikalık Nefes Meditasyonu',N'İş yerinde yapabileceğiniz teknikler',N'<p>Derin nefes alma teknikleri kortizol seviyesini düşürür ve anı farkındalığı artırır. Gözlerinizi kapatın, 4 saniye nefes alın, 4 saniye tutun, 6 saniye verin. Beş tekrar yeterlidir.</p>',N'blog-7',N'img/blog-nefes.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Wellness & Meditasyon' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424720',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Mindfulness ve Günlük Hayat') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Mindfulness ve Günlük Hayat',N'Her anda tam anlamıyla var olmak',N'<p>Mindfulness, geçmiş ya da geleceğe takılmadan şu ana odaklanmaktır. Yemek yerken, yürürken veya uyumadan önce birkaç dakika bilinçli nefes egzersizi yapmak başlangıç için yeterlidir.</p>',N'blog-8',N'img/blog-mindfulness.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Wellness & Meditasyon' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424718',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Dijital Detoks: Telefondan Uzak Kalmak') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Dijital Detoks: Telefondan Uzak Kalmak',N'Zihin sağlığı için ekran molası',N'<p>Günde en az 2 saat ekrandan uzak bir ''dijital suskunluk'' dönemi geçirmek uyku kalitesini ve odaklanmayı istatistiksel olarak %37 artırmaktadır. Yatmadan 1 saat önce başlayın.</p>',N'blog-9',N'img/blog-dijital-detoks.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Wellness & Meditasyon' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424713',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Lavanta Yağının 7 Faydası') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Lavanta Yağının 7 Faydası',N'Doğanın en çok yönlü esansı',N'<p>Lavanta esansiyel yağı; uyku düzenini iyileştirir, kaygıyı azaltır, hafıza ağrısını dindirir, cilt tahrişini giderir, yara iyileşmesini hızlandırır, böcekleri uzaklaştırır ve saç büyümesini destekler.</p>',N'blog-10',N'img/blog-lavanta.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Aromaterapi' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424693',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Difüzör Kullanımı Rehberi') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Difüzör Kullanımı Rehberi',N'Odanızı aromaterapi cennetine çevirin',N'<p>Difüzör seçerken ultrasonik modeller tercih edin. Dam başına 3-5 damla yağ yeterlidir. Çay ağacı ve ökaliptüs kombinasyonu sabah, lavanta ve papatya karışımı gece için idealdir.</p>',N'blog-11',N'img/blog-difuzor.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Aromaterapi' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424751',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'3 Günlük Bahar Detoks Programı') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'3 Günlük Bahar Detoks Programı',N'İçinizi baharla temizleyin',N'<p>1. gün: Yalnızca sıvı gıdalar. 2. gün: Çiğ sebze ve meyve. 3. gün: Hafif pişirilmiş yiyecekler. Bol su, yeşil çay ve taze sıkılmış meyve suları tüm program boyunca serbesttir.</p>',N'blog-12',N'img/blog-detoks.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Beslenme & Detoks' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424753',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Kolajen Üretimini Artıran 8 Besin') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Kolajen Üretimini Artıran 8 Besin',N'Mutfağınızdan güzellik reçetesi',N'<p>C vitamini (kivi, biber), çinko (kabak çekirdeği, yumurta), bakır (kakao, susam) ve glisin (kemik suyu, jelatin) kolajen sentezini destekler. Bu besinleri günlük diyetinize ekleyin.</p>',N'blog-13',N'img/blog-kolajen.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Beslenme & Detoks' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424755',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Türk Hamamı Deneyimi: Neler Beklemelisiniz?') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Türk Hamamı Deneyimi: Neler Beklemelisiniz?',N'Geleneksel temizlik ritüeli',N'<p>Geleneksel Türk hamamında önce soyunma odası (camekan), ardından ılıklık (ılıcak) ve sıcaklık (hararet) bölümlerine geçilir. Kese ve köpük masajı cildi derinlemesine temizler.</p>',N'blog-14',N'img/blog-hamam.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Hamam & Sauna' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424757',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Sauna ve Bağışıklık Sistemi İlişkisi') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Sauna ve Bağışıklık Sistemi İlişkisi',N'Düzenli saunanın bilimsel kanıtları',N'<p>Haftada 2-3 kez yapılan sauna seanları, belediyenin bağışıklık hücrelerini aktive eder. Finlandiya''da yapılan uzun dönem araştırmalar kalp hastalığı riskini %40 azalttığını göstermiştir.</p>',N'blog-15',N'img/blog-sauna.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Hamam & Sauna' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424759',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Retinol Kullanımının Püf Noktaları') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Retinol Kullanımının Püf Noktaları',N'Yanlış kullanmaktan kaçının',N'<p>Retinol güçlü bir A vitamini türevidir. Başlangıçta haftada 2 gece kullanın. Güneş koruyucu olmadan gündüz uygulamayın. Hamilelikte kesinlikle kullanmayın. 6-8 haftada sonuç görürsünüz.</p>',N'blog-16',N'img/blog-retinol.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Anti-Aging' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424763',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Gözaltı Kırışıklıklarına Karşı Doğal Yöntemler') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Gözaltı Kırışıklıklarına Karşı Doğal Yöntemler',N'Kimyasal olmadan genç görünün',N'<p>Soğuk papatya çayı poşeti, buz küresi masajı ve göz çevresi için özel jeller gözaltı kırışıklıklarını belirgin biçimde azaltır. Uyku düzeni ve güneş koruyucu en büyük destekçinizdir.</p>',N'blog-17',N'img/blog-gozalti.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Anti-Aging' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424765',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Keratin Tedavisi Nedir ve Ne Kadar Sürer?') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Keratin Tedavisi Nedir ve Ne Kadar Sürer?',N'Pürüzsüz saçların sırrı',N'<p>Keratin tedavisi, saçın dış katmanını doldurarak friziness ve kıvrımı azaltır. Teknik olarak 2-4 saat sürer ve 3-5 ay kalıcı olabilir. Sülfatsız şampuan kullanımı ömrü uzatır.</p>',N'blog-18',N'img/blog-keratin.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Saç Bakımı' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424767',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Hindistan Cevizi Yağının Saça Faydaları') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Hindistan Cevizi Yağının Saça Faydaları',N'Mutfak malzemesiyle saç bakımı',N'<p>Saf hindistan cevizi yağı, saç teline nüfuz ederek protein kaybını önler. Yıkama öncesi maske olarak 30 dakika uygulamak yeterlidir. Yağlı saçlar için ucuçlardan köklere gidin.</p>',N'blog-19',N'img/blog-hindistancevizi.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Saç Bakımı' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424768',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Sabah Yogası: 10 Dakikada Güne Başlangıç') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Sabah Yogası: 10 Dakikada Güne Başlangıç',N'Uyku sersemliğini hızla atın',N'<p>Yataktan kalkar kalkmaz; kedi-inek hareketi, çocuk pozu ve güneş selamlama serisi kan dolaşımını hızlandırır ve enerji verir. DVD ya da uygulama gerekmez, birkaç mat yeterli.</p>',N'blog-20',N'img/blog-yoga.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Yoga & Pilates' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424771',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Pilates ve Duruş Bozukluğu') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Pilates ve Duruş Bozukluğu',N'Masa başı çalışanlar için çözüm',N'<p>Pilates core kaslarını güçlendirerek omurga desteğini artırır. Haftada 3 seans düzenli pilates, 3 ay içinde postür bozukluğunu gözle görülür şekilde iyileştirir.</p>',N'blog-21',N'img/blog-pilates.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Yoga & Pilates' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424773',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Düzenli Su İçmenin Cilde Etkisi') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Düzenli Su İçmenin Cilde Etkisi',N'En ucuz güzellik sırrı',N'<p>Günlük 2-2,5 litre su içmek; cilt nem dengesini korur, gözeneklerin görünümünü azaltır ve toksik maddelerin atılımını hızlandırır. Sabah aç karnına içilen 1 bardak ılık su özellikle faydalıdır.</p>',N'blog-22',N'img/blog-su.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Genel Sağlık' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424775',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Uyku Kalitesi Cilt Sağlığını Nasıl Etkiler?') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Uyku Kalitesi Cilt Sağlığını Nasıl Etkiler?',N'Güzellik uykusu gerçek mi?',N'<p>Uyku sırasında salgılanan büyüme hormonu hücre yenilenmesini tetikler. 7-9 saat kaliteli uyku alan bireylerin ciltleri %30 daha verimli onarılır. Yan uyumak kırışıklık oluşturabilir; sırtüstü uyumak önerilir.</p>',N'blog-23',N'img/blog-uyku.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Genel Sağlık' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424777',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Egzersiz Sonrası Cilt Bakımı Rutini') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Egzersiz Sonrası Cilt Bakımı Rutini',N'Terin ardından ne yapmalısınız',N'<p>Egzersiz sonrası ilk 20 dakika içinde yüzünüzü yıkayın. Gözenekleri tıkamayan hafif nemlendirici kullanın. Ter birikimi akne ve cilt tahrişine yol açar; bu nedenle temizlik önemlidir.</p>',N'blog-24',N'img/blog-bakim.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Cilt Bakımı' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424780',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Stres ve Cilt: Kortizolün Etkisi') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Stres ve Cilt: Kortizolün Etkisi',N'Stres neden sivilce yapar?',N'<p>Kortizol hormonu yağ bezlerini uyararak sebum üretimini artırır. Kronik stres; akne, egzema ve sedef hastalığını tetikleyebilir. Meditasyon ve egzersiz kortizolü doğal yolla düşürür.</p>',N'blog-25',N'img/blog-stres.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Cilt Bakımı' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424782',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Güneş Koruyucu Her Mevsim Şart mı?') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Güneş Koruyucu Her Mevsim Şart mı?',N'Bulutlu günlerde de UV var',N'<p>UVA ışınları bulutları geçer ve cam camı deler. Kış ve ilkbaharda da SPF 30+ kullanmak erken yaşlanmayı ve cilt kanserini önler. Kimyasal filtreler güneş öncesi, mineral filtreler hemen uygulanabilir.</p>',N'blog-26',N'img/blog-gunes.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Cilt Bakımı' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424786',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'Spa Öncesi Yapılmaması Gerekenler') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'Spa Öncesi Yapılmaması Gerekenler',N'Seans veriminizi artırın',N'<p>Spa randevusundan 24 saat önce tüy alma işlemi yaptırmayın. Ağır yemek yemeyin, alkol almayın. Yoğun egzersiz yapmaktan kaçının. Bu önlemler hem konforunuzu artırır hem de ürünlerin emilimini iyileştirir.</p>',N'blog-27',N'img/blog-spa-oncesi.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Masaj Teknikleri' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424788',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.Blogs WITH(UPDLOCK,HOLDLOCK) WHERE Title=N'İlk Kez Spa''ya Gidenler İçin Rehber') BEGIN INSERT dbo.Blogs(Title,SubTitle,Content,Slug,Image,CatagoryId,AppUserId,PublishStatus,IsPublish,IsDeleted,CreatedDate,CreatedBy) VALUES(N'İlk Kez Spa''ya Gidenler İçin Rehber',N'Ne giyilir, ne beklenir?',N'<p>İlk spa ziyaretinizde rahat iç çamaşırı giyin; tesis genellikle havlu sağlar. Değerli takı ve elektronik cihazlarınızı evde bırakın. Seans öncesi 15 dakika erken gelinmesi önerilir.</p>',N'blog-29',N'img/blog-ilk-spa.webp',(SELECT TOP(1) Id FROM dbo.Catagories WHERE Title=N'Wellness & Meditasyon' ORDER BY Id),NULL,2,1,0,CONVERT(datetime2,N'2026-10-01T12:00:28.3424792',126),N'editorial-transfer-20261018'); SET @blogs+=1; END;
